13	/** A capsule on its side, split — the stack, and the schedule cutting it up. */
14	export function LogoMark({ size = 20, color = 'var(--accent)' }: { size?: number; color?: string }) {
15	  return (
16	    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden>
17	      <rect x="2.6" y="7.4" width="18.8" height="9.2" rx="4.6" stroke={color} strokeWidth="1.9" />
18	      <path d="M12 7.4v9.2" stroke={color} strokeWidth="1.9" strokeLinecap="round" />
19	    </svg>
20	  );
21	}
22	
23	/**
24	 * One segment per step. Filled segments are the steps behind you, so it can
25	 * never claim "87% complete" on step four — the denominator is the real flow
26	 * length and every segment is the same width.
27	 */
28	export function ProgressBar({ step }: { step: Step }) {
29	  const index = FLOW.indexOf(step);
30	  return (
31	    <div
32	      className="ob-progress"
33	      role="progressbar"
34	      aria-valuemin={1}
